/**
 * The storefront's copy, in both languages.
 *
 * Arabic is Modern Standard, which is what a Gulf shopper expects to read from
 * a business — dialect reads as informal in commerce, and MSA is understood
 * across all six governorates and the wider Gulf. Terms follow the vocabulary
 * the regional marketplaces already use, so nothing has to be decoded:
 * "أضف إلى السلة" for add-to-cart, "اشترِ الآن" for buy now, "المحفوظات" for
 * saved items, "الدفع" for checkout.
 *
 * One dictionary keyed by string, not two files that drift: `ar` is typed as a
 * complete record of the English keys, so a missing translation is a type
 * error rather than an English word appearing mid-Arabic-sentence.
 *
 * The brand is written نت‑لت in Arabic — Latin "NetLet" set inside RTL text
 * forces the reader's eye to change direction mid-line, and the bidi algorithm
 * puts adjacent punctuation on the wrong side of it.
 */
import { pluralForm } from "./plurals.js";

export const LOCALES = ["en", "ar"] as const;
export type LocaleCode = (typeof LOCALES)[number];

