  "notice.emailFooterStaff": "You get these emails because you administer NetLet. To stop them, turn off emails in your preferences:",
  "notices.title": "Notifications",
  "notices.empty": "Nothing here yet. When an order moves, an item you follow is back or cheaper, or somebody replies to you, it appears here.",
  "notices.markAll": "Mark all as read",
  "notices.unread": "{count} unread",
  "notices.new": "New",
  "notices.email": "Also send these to my email",
  "notices.emailNote": "Back-in-stock, price and order updates go to {email}. New arrivals stay here only.",
  "notices.tile": "Updates on your orders and the items you follow",
  "notices.menu": "Notifications",
  "sell.readAgreement": "Read the seller agreement",
  "privacy.title": "Privacy policy",
  "privacy.intro": "This page explains what NetLet keeps about you, why, and who else sees it. NetLet is run by {operator}.",
  "privacy.introPlain": "This page explains what NetLet keeps about you, why, and who else sees it.",
  "privacy.keep.title": "What we keep",
  "privacy.keep.account": "Your account: your name, your email address and your language. Your password is held as a one-way code by our sign-in service, so nobody at NetLet can read it.",
  "privacy.keep.profile": "Your profile, if you add them: a phone number, your gender, your birthday and your nationality. Each is optional and can be removed on Your profile. None of them is shown to a store; the phone number is filled in at checkout as the number the driver calls, and you can change it there.",
  "privacy.keep.orders": "Your orders: what you bought, the delivery addresses and phone number you gave, and the map pin if you placed one.",
  "privacy.keep.writing": "What you write to us or to a store — messages, reviews and return requests — and the products and lists you save.",
  "privacy.keep.selling": "If you apply to sell: your store's details and the documents you upload, which only you and NetLet's administrators can open.",
  "privacy.device.title": "What stays on your device",
  "privacy.device.body": "Two things are kept only in your browser and never sent to us: your recent searches, and your measurements if you ask the size guide to remember them.",
  "privacy.why.title": "Why we use it",
  "privacy.why.orders": "To take your order and bring it to your door, to show you your account, to answer you when you ask for help, and to issue the invoices the law requires.",
  "privacy.why.abuse": "To stop fraud and abuse: we count failed sign-ins and some repeated requests by network (IP) address, and keep those counts only for a short time.",
  "privacy.why.picked": "“Picked for you” uses what you saved, added to your bag and bought on NetLet. Only general interest words leave NetLet for it — never your name, email or orders.",
  "privacy.who.title": "Who else sees it",
  "privacy.who.stores": "The stores you order from, and the company delivering for them, see what they need to deliver: your name, address, phone number and the items. In messages and reviews a store sees your first name and initial, never your email.",
  "privacy.who.services": "The services that run NetLet for us: our hosting (Vercel), and our database and sign-in service (Supabase), which also sends your verification codes and password emails.",
  "privacy.who.email": "Our email service (Resend) sends the updates in your NetLet inbox to your email address — your orders, the items you follow, replies to your messages — unless you turn that off in your notifications.",
  "privacy.who.tryOn": "When you try a product on, the photo of yourself you choose goes, with the product's photo, to Google's Gemini AI model to draw you wearing it. NetLet does not keep your photo or the picture it draws.",
  "privacy.who.google": "When you create an account, Google's reCAPTCHA checks that you are not a robot. When you place a pin, the map you choose — Google Maps, Apple Maps or OpenStreetMap — loads in your browser.",
  "privacy.who.placeLookup": "When you drop a pin, its point — and nothing else about you — goes to OpenStreetMap's address service, and to Apple Maps when the shop has it set up, to read the area, block and street at that spot.",
  "privacy.who.ai": "When you ask the shop assistant, a product's assistant or the help page a question, or search with a photo, the question or the photo goes to Google's Gemini AI model, through a NetLet service that runs on Cloudflare, with the product's own text where you are on one; your name, email, address and orders do not. When you search by voice, your browser's own speech service hears it.",
  "privacy.who.drivers": "If you deliver for NetLet, your location is shared only while you switch sharing on, and only with the shopper whose parcel you are carrying.",
  "privacy.who.drivingTimes": "While a driver shares their location, where they are and the pin on the address they are driving to go to Apple Maps, which answers how long the drive takes in today's traffic. Nothing else goes with them — no name, order or account.",
  "privacy.who.sell": "We do not sell your information, and we do not share it for advertising.",
  "privacy.cookies.title": "Cookies",
  "privacy.cookies.body": "NetLet sets one cookie, to keep you signed in, and no advertising cookies. On the Create account form, Google's reCAPTCHA may set cookies of its own.",
  "privacy.cookies.analytics": "We count visits with an analytics tool that sets no cookies and does not identify you.",
  "privacy.long.title": "How long we keep it",
  "privacy.long.body": "Your account details for as long as your account is open. Orders and invoices for as long as Kuwaiti law requires a business to keep its records, even after an account is closed.",
  "privacy.choices.title": "Your choices",
  "privacy.choices.body": "You can see and change your name, email, password, addresses and language from Your account. To close your account and delete what we hold, ask us through Help; we keep only what the law requires.",
  "privacy.changes.title": "Changes",
  "privacy.changes.body": "If this policy changes, the date at the top changes with it.",

