  "notice.staffFraudReferral": "تصنّف مراقبة الاحتيال إحالةً صُرفت مكافأتها للتو عالية الخطورة — فقد يكون الحسابان لشخص واحد. راجعها قبل صرف النقاط.",
  "notice.emailOpen": "افتح في نت‑لت",
  "notice.emailFooter": "تصلك هذه الرسائل لأن لديك حساباً في نت‑لت. لإيقافها، أوقف رسائل البريد في تفضيلاتك:",
  "notice.emailFooterSeller": "تصلك هذه الرسائل لأنك تعمل في متجر على نت‑لت. لإيقافها، أوقف رسائل البريد في تفضيلاتك:",
  "notice.emailFooterStaff": "تصلك هذه الرسائل لأنك تدير نت‑لت. لإيقافها، أوقف رسائل البريد في تفضيلاتك:",
  "notices.title": "الإشعارات",
  "notices.empty": "لا شيء هنا بعد. حين يتحرك طلب، أو يعود منتج تتابعه أو ينخفض سعره، أو يردّ عليك أحد، يظهر هنا.",
